package com.example.agroconnect.controller;
import com.example.agroconnect.model.*; import com.example.agroconnect.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/finance") @CrossOrigin(origins="http://localhost:5173",allowCredentials="true") public class FarmFinanceController {
 private final FarmTransactionRepository transactions; private final FarmerRepository farmers; public FarmFinanceController(FarmTransactionRepository t,FarmerRepository f){transactions=t;farmers=f;}
 private boolean allowed(Farmer f,HttpSession s){Object uid=s.getAttribute("userId");return uid!=null&&("ADMIN".equals(s.getAttribute("role"))||(f.getUser()!=null&&f.getUser().getId().toString().equals(uid.toString())));}
 @GetMapping("/farmer/{farmerId}") public ResponseEntity<?> list(@PathVariable Long farmerId,HttpSession s){Farmer f=farmers.findById(farmerId).orElse(null);if(f==null)return ResponseEntity.notFound().build();if(!allowed(f,s))return ResponseEntity.status(403).body("Not allowed");List<FarmTransaction> rows=transactions.findByFarmerIdOrderByTransactionDateDesc(farmerId);double income=rows.stream().filter(x->"INCOME".equals(x.getType())).mapToDouble(FarmTransaction::getAmount).sum();double expenses=rows.stream().filter(x->"EXPENSE".equals(x.getType())).mapToDouble(FarmTransaction::getAmount).sum();Map<String,Object> out=new LinkedHashMap<>();out.put("transactions",rows);out.put("totalIncome",income);out.put("totalExpenses",expenses);out.put("profitOrLoss",income-expenses);return ResponseEntity.ok(out);}
 @PostMapping("/farmer/{farmerId}") public ResponseEntity<?> add(@PathVariable Long farmerId,@RequestBody FarmTransaction t,HttpSession s){Farmer f=farmers.findById(farmerId).orElse(null);if(f==null)return ResponseEntity.notFound().build();if(!allowed(f,s))return ResponseEntity.status(403).body("Not allowed");if(t.getAmount()<=0||t.getType()==null||!(t.getType().equals("INCOME")||t.getType().equals("EXPENSE")))return ResponseEntity.badRequest().body("Type must be INCOME or EXPENSE and amount must be positive");t.setId(null);t.setFarmer(f);if(t.getTransactionDate()==null)t.setTransactionDate(LocalDate.now());return ResponseEntity.ok(transactions.save(t));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id,HttpSession s){FarmTransaction t=transactions.findById(id).orElse(null);if(t==null)return ResponseEntity.notFound().build();if(!allowed(t.getFarmer(),s))return ResponseEntity.status(403).body("Not allowed");transactions.delete(t);return ResponseEntity.ok(Map.of("message","Transaction deleted"));}
}
